void lpc1765_sync() {
    // 1. Send sync character for autobaud
    uart_puts(UART_ID, "?");
    sleep_ms(50); 

    // 2. Acknowledge synchronization
    uart_puts(UART_ID, "Synchronized\r\n");
    sleep_ms(50);

    // 3. Set clock (assuming 12MHz crystal -> 12000 kHz)
    uart_puts(UART_ID, "12000\r\n");
    sleep_ms(50);

    // Clear out any incoming responses ("OK\r\n") from the RX FIFO
    while(uart_is_readable(UART_ID)) {
        uart_getc(UART_ID);
    }
