void bitbang_newline_and_glitch() {
    uint32_t bit_delay_us = 1000000 / BAUD_RATE;
    uint8_t byte = '\n'; // 0x0A

    // Pre-set GPIO state to HIGH before taking over the pin to avoid false start bits
    gpio_put(UART_TX_PIN, 1);
    gpio_set_function(UART_TX_PIN, GPIO_FUNC_SIO);
    gpio_set_dir(UART_TX_PIN, GPIO_OUT);

    // Start bit (LOW)
    gpio_put(UART_TX_PIN, 0);
    busy_wait_us_32(bit_delay_us);

    // 8 Data bits (LSB first)
    for (int i = 0; i < 8; i++) {
        gpio_put(UART_TX_PIN, (byte >> i) & 1);
        busy_wait_us_32(bit_delay_us);
    }

    // Stop bit (HIGH)
    gpio_put(UART_TX_PIN, 1);
    busy_wait_us_32(bit_delay_us);

    // --- CRITICAL TIMING SECTION ---

    // Wait the exact delay required before the glitch
    busy_wait_us_32(GLITCH_DELAY_US);

    // Fire the glitch pin
    gpio_put(GLITCH_PIN, 1);
    busy_wait_us_32(GLITCH_WIDTH_US);
    gpio_put(GLITCH_PIN, 0);

    // Restore TX pin back to hardware UART control
    gpio_set_function(UART_TX_PIN, GPIO_FUNC_UART);
}```

